struct msg_hdr { uint16_t type; uint16_t len; };   /* token travels first */
static const struct { uint16_t type; int (*parse)(const uint8_t *, size_t); } readers[] = {
    { MSG_ORDER_CREATED, order_created_parse },
    { MSG_ORDER_SHIPPED, order_shipped_parse },
};
const struct msg_hdr *h = (const struct msg_hdr *)buf;   /* before any body access */
if (n < sizeof *h || h->len > n - sizeof *h) return -EMSGSIZE;
for (size_t i = 0; i < sizeof readers / sizeof readers[0]; i++)
    if (readers[i].type == h->type) return readers[i].parse(buf + sizeof *h, h->len);
return -EPROTONOSUPPORT;                                 /* unknown token: reject */
